// CountRules counts all rules
func (s *Store) CountRules(ctx context.Context, namespaceKey, flagKey string) (uint64, error) {
	if namespaceKey == "" {
		namespaceKey = storage.DefaultNamespace
	}

	var count uint64

	if err := s.builder.Select("COUNT(*)").
		From("rules").
		Where(sq.And{sq.Eq{"namespace_key": namespaceKey}, sq.Eq{"flag_key": flagKey}}).
		QueryRowContext(ctx).
		Scan(&count); err != nil {
		return 0, err
	}

	return count, nil
}

// CreateRule creates a rule
func (s *Store) CreateRule(ctx context.Context, r *flipt.CreateRuleRequest) (_ *flipt.Rule, err error) {
	segmentKeys := sanitizeSegmentKeys(r.GetSegmentKey(), r.GetSegmentKeys())

	if r.NamespaceKey == "" {
		r.NamespaceKey = storage.DefaultNamespace
	}

	var (
		now  = timestamppb.Now()
		rule = &flipt.Rule{
			Id:              uuid.Must(uuid.NewV4()).String(),
			NamespaceKey:    r.NamespaceKey,
			FlagKey:         r.FlagKey,
			Rank:            r.Rank,
			SegmentOperator: r.SegmentOperator,
			CreatedAt:       now,
			UpdatedAt:       now,
		}
	)

	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}

	defer func() {
		if err != nil {
			_ = tx.Rollback()
		}
	}()

	if _, err := s.builder.
		Insert("rules").
		RunWith(tx).
		Columns("id", "namespace_key", "flag_key", "\"rank\"", "segment_operator", "created_at", "updated_at").
		Values(
			rule.Id,
			rule.NamespaceKey,
			rule.FlagKey,
			rule.Rank,
			rule.SegmentOperator,
			&fliptsql.Timestamp{Timestamp: rule.CreatedAt},
			&fliptsql.Timestamp{Timestamp: rule.UpdatedAt},
		).
		ExecContext(ctx); err != nil {
		return nil, err
	}

	for _, segmentKey := range segmentKeys {
		if _, err := s.builder.
			Insert("rule_segments").
			RunWith(tx).
			Columns("rule_id", "namespace_key", "segment_key").
			Values(
				rule.Id,
				rule.NamespaceKey,
				segmentKey,
			).
			ExecContext(ctx); err != nil {
			return nil, err
		}
	}

	if len(segmentKeys) == 1 {
		rule.SegmentKey = segmentKeys[0]
	} else {
		rule.SegmentKeys = segmentKeys
	}

	return rule, tx.Commit()
}

// UpdateRule updates an existing rule
func (s *Store) UpdateRule(ctx context.Context, r *flipt.UpdateRuleRequest) (_ *flipt.Rule, err error) {
	segmentKeys := sanitizeSegmentKeys(r.GetSegmentKey(), r.GetSegmentKeys())

	if r.NamespaceKey == "" {
		r.NamespaceKey = storage.DefaultNamespace
	}

	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}

	defer func() {
		if err != nil {
			_ = tx.Rollback()
		}
	}()

	// Set segment operator.
	_, err = s.builder.Update("rules").
		RunWith(tx).
		Set("segment_operator", r.SegmentOperator).
		Set("updated_at", &fliptsql.Timestamp{Timestamp: timestamppb.Now()}).
		Where(sq.And{sq.Eq{"id": r.Id}, sq.Eq{"namespace_key": r.NamespaceKey}, sq.Eq{"flag_key": r.FlagKey}}).
		ExecContext(ctx)
	if err != nil {
		return nil, err
